    [MenuItem( "Swordsman/Static HD Preview/Build And Validate Bundle" )]
    public static void BuildAndValidateApprovedBundleMenu()
    {
        string bundlePath = BuildAndValidateApprovedBundle();
        Debug.Log( "SWORDSMAN_HD4X_BUNDLE_READY path=" + bundlePath );
    }

    public static string BuildAndValidateApprovedBundle()
    {
        return BuildAndValidateCachedBundle();
    }

    public static string ValidateExistingApprovedBundle( string expectedSha256 )
    {
        if ( expectedSha256 == null || expectedSha256.Length != 64 ) throw new InvalidOperationException( "A locked bundle SHA256 is required." );
        string root = Path.GetFullPath( Path.Combine( Application.dataPath, ".." ) );
        foreach ( AtlasSpec spec in SpriteAtlases ) ValidateApprovedAsset( root, spec.asset );
        foreach ( ApprovedAsset asset in SingleAssets ) ValidateApprovedAsset( root, asset );
        string path = Path.Combine( root, BundleOutputRelativePath, BundleName );
        ValidateHash( path, expectedSha256, "Previously verified HD bundle" );
        ValidateBuiltBundle( path );
        return path;
    }

    public static void StageBundleForPlayer( string bundlePath )
    {
        if ( string.IsNullOrEmpty( bundlePath ) || !File.Exists( bundlePath ) )
        {
            throw new FileNotFoundException( "HD AssetBundle is missing.", bundlePath );
        }

        removeStreamingAssetsRootAfterBuild =
            !Directory.Exists( GetAbsoluteProjectPath( StreamingAssetsRoot ) );
        EnsureReservedFolderCanBeReplaced( StreamingFolder );
        Directory.CreateDirectory( GetAbsoluteProjectPath( StreamingFolder ) );
        File.Copy( bundlePath, GetAbsoluteProjectPath( StreamingBundlePath ), false );
        AssetDatabase.ImportAsset( StreamingBundlePath, ImportAssetOptions.ForceSynchronousImport );
    }

    public static void RemoveStagedPlayerBundle()
    {
        if ( !AssetDatabase.IsValidFolder( StreamingFolder ) )
        {
            return;
        }

        string[] files = Directory.GetFiles( GetAbsoluteProjectPath( StreamingFolder ) );
        for ( int i = 0; i < files.Length; i++ )
        {
            string fileName = Path.GetFileName( files[ i ] );
            if ( fileName != BundleName && fileName != BundleName + ".meta" )
            {
                throw new InvalidOperationException(
                    "Reserved HD StreamingAssets folder contains an unexpected file: " + files[ i ] );
            }
        }

        AssetDatabase.DeleteAsset( StreamingFolder );
        if ( removeStreamingAssetsRootAfterBuild &&
            Directory.Exists( GetAbsoluteProjectPath( StreamingAssetsRoot ) ) &&
            Directory.GetFileSystemEntries(
                GetAbsoluteProjectPath( StreamingAssetsRoot ) ).Length == 0 )
        {
            AssetDatabase.DeleteAsset( StreamingAssetsRoot );
        }
        removeStreamingAssetsRootAfterBuild = false;
        AssetDatabase.Refresh();
    }

    static void ValidateApprovedAsset( string projectRoot, ApprovedAsset asset )
    {
        string approvedPath = Path.Combine( projectRoot, asset.approvedRelativePath );
        string sourcePath = Path.Combine( projectRoot, asset.sourceAssetPath );
        ValidateHash( approvedPath, asset.approvedSha256, "Approved " + asset.label );
        SourceTexture frozen;
        if (TryFrozenSource(asset.sourceAssetPath, out frozen))
        {
            if (frozen.hash != asset.sourceSha256) throw new InvalidOperationException("Retired source provenance mismatch: " + asset.label);
            if (File.Exists(sourcePath)) ValidateHash(sourcePath, asset.sourceSha256, "Source " + asset.label);
        }
        else ValidateHash(sourcePath, asset.sourceSha256, "Source " + asset.label);
    }

    static void ValidateHash( string path, string expectedSha256, string label )
    {
        if ( !File.Exists( path ) )
        {
            throw new FileNotFoundException( label + " is missing.", path );
        }

        string actualHash = GetSha256( path );
        if ( !string.Equals( actualHash, expectedSha256, StringComparison.OrdinalIgnoreCase ) )
        {
            throw new InvalidOperationException(
                label + " hash mismatch. expected=" + expectedSha256 + " actual=" + actualHash );
        }
    }

    static void CopyApprovedAssetToStaging( string projectRoot, ApprovedAsset asset )
    {
        string stagingAbsolutePath = GetAbsoluteProjectPath( asset.stagingPath );
        Directory.CreateDirectory( Path.GetDirectoryName( stagingAbsolutePath ) );
        File.Copy(
            Path.Combine( projectRoot, asset.approvedRelativePath ),
            stagingAbsolutePath,
            false );
    }

    static void ConfigureSingleImporter( ApprovedAsset asset )
    {
        TextureImporter importer = AssetImporter.GetAtPath( GetHdCacheAssetPath( asset.stagingPath ) ) as TextureImporter;
        if ( importer == null )
        {
            throw new InvalidOperationException(
                "Cannot obtain the HD TextureImporter for " + asset.label );
        }

        SourceSprite legacySprite = GetSourceSpriteGeometry( asset.sourceAssetPath );
        if ( legacySprite == null || legacySprite.pixelsPerUnit <= 0.0f )
        {
            throw new InvalidOperationException( "Cannot obtain source Sprite PPU for " + asset.label );
        }

        ConfigureCommonImporter( importer, asset.maxTextureSize );
        importer.spriteImportMode = SpriteImportMode.Single;
        importer.spritePixelsPerUnit = legacySprite.pixelsPerUnit * SingleScale;
        TextureImporterSettings settings = new TextureImporterSettings();
        importer.ReadTextureSettings( settings );
        settings.spriteAlignment = (int)SpriteAlignment.Custom;
        settings.spritePivot = new Vector2( 0.0f, 1.0f );
        importer.SetTextureSettings( settings );
        importer.SaveAndReimport();
    }

    static void ConfigureAtlasImporter( AtlasSpec spec )
    {
        List<SourceSprite> legacySprites = FindLegacySpritesForTexture( spec.asset.sourceAssetPath, spec.allowedSpriteName );
        if ( legacySprites.Count != spec.expectedSpriteCount )
        {
            throw new InvalidOperationException(
                spec.asset.label + " source Sprite count mismatch: " + legacySprites.Count );
        }

        TextureImporter importer = AssetImporter.GetAtPath(
            GetHdCacheAssetPath( spec.asset.stagingPath ) ) as TextureImporter;
        if ( importer == null )
        {
            throw new InvalidOperationException(
                "Cannot obtain the HD atlas TextureImporter for " + spec.asset.label );
        }

        float sourcePpu = legacySprites[ 0 ].pixelsPerUnit;
        SpriteMetaData[] metadata = new SpriteMetaData[ legacySprites.Count ];
        for ( int i = 0; i < legacySprites.Count; i++ )
        {
            SourceSprite sprite = legacySprites[ i ];
            if ( !Mathf.Approximately( sprite.pixelsPerUnit, sourcePpu ) )
            {
                throw new InvalidOperationException(
                    spec.asset.label + " contains mixed source PPU values." );
            }
            metadata[ i ] = new SpriteMetaData
            {
                name = sprite.name,
                rect = GetAtlasRect( sprite, spec ),
                alignment = (int)SpriteAlignment.Custom,
                pivot = new Vector2(
                    sprite.pivot.x / sprite.rect.width,
                    sprite.pivot.y / sprite.rect.height ),
                border = sprite.border * spec.linearScale,
            };
        }

        ConfigureCommonImporter( importer, spec.asset.maxTextureSize );
        // Legacy treasure Type2 derives alpha from RGB, so transparent RGB must stay black.
        if ( spec.asset.sourceAssetPath == "Assets/Texture2D/TREASURE.png" || spec.asset.stagingPath.Contains( "/Omissions/" ) ) importer.alphaIsTransparency = false;
        if ( spec.asset.stagingPath.Contains( "/Omissions/" ) )
        {
            var settings = new TextureImporterSettings();
            importer.ReadTextureSettings( settings );
            settings.spriteMeshType = SpriteMeshType.FullRect;
            importer.SetTextureSettings( settings );
        }
        importer.spriteImportMode = SpriteImportMode.Multiple;
        importer.spritePixelsPerUnit = sourcePpu * spec.linearScale;
        importer.spritesheet = metadata;
        importer.SaveAndReimport();
    }

    static List<Sprite> FindLiveSourceSprites( string texturePath, string allowedSpriteName )
    {
        Sprite directSprite = AssetDatabase.LoadAssetAtPath<Sprite>( texturePath );
        if ( directSprite != null && allowedSpriteName == directSprite.name )
            return new List<Sprite> { directSprite };
        string filter = allowedSpriteName == null || allowedSpriteName.Contains( "|" )
            ? Path.GetFileNameWithoutExtension( texturePath ) : allowedSpriteName;
        string[] guids = AssetDatabase.FindAssets( filter + " t:Sprite", new[] { "Assets/Sprite" } );
        List<Sprite> matches = new List<Sprite>();
        for ( int i = 0; i < guids.Length; i++ )
        {
            string assetPath = AssetDatabase.GUIDToAssetPath( guids[ i ] );
            Sprite sprite = AssetDatabase.LoadAssetAtPath<Sprite>( assetPath );
            if ( sprite != null && sprite.texture != null &&
                ( allowedSpriteName == null || Array.IndexOf( allowedSpriteName.Split( '|' ), sprite.name ) >= 0 ) &&
                string.Equals(
                    AssetDatabase.GetAssetPath( sprite.texture ),
                    texturePath,
                    StringComparison.OrdinalIgnoreCase ) )
            {
                matches.Add( sprite );
            }
        }
        matches.Sort( ( first, second ) => string.CompareOrdinal( first.name, second.name ) );
        return matches;
    }

