    static Rect GetAtlasRect( SourceSprite sprite, AtlasSpec spec )
    {
        Rect rect = ScaleRect( sprite.rect, spec.linearScale );
        if ( spec.standaloneSlice )
        {
            rect.position = Vector2.zero;
            return rect;
        }
        Vector2 origin;
        if ( ( spec.asset.label == "MSG_BOX" && RepackedMsgBoxOrigins.TryGetValue( sprite.name, out origin ) ) ||
             ( ( spec.asset.label == "Item_win" || spec.asset.label == "Sqw_int" ) &&
               RepackedShopUiOrigins.TryGetValue( sprite.name, out origin ) ) )
        {
            rect.position = origin;
        }
        return rect;
    }

    static Rect ScaleRect( Rect rect, float scale )
    {
        return new Rect(
            rect.x * scale,
            rect.y * scale,
            rect.width * scale,
            rect.height * scale );
    }

    static void ConfigureCommonImporter( TextureImporter importer, int maxTextureSize )
    {
        importer.textureType = TextureImporterType.Sprite;
        importer.mipmapEnabled = false;
        importer.alphaIsTransparency = true;
        importer.filterMode = FilterMode.Bilinear;
        importer.wrapMode = TextureWrapMode.Clamp;
        importer.npotScale = TextureImporterNPOTScale.None;
        importer.maxTextureSize = maxTextureSize;
        importer.textureCompression = TextureImporterCompression.Uncompressed;
    }

    static void ValidateStaticBundleAssets( AssetBundle bundle )
    {
        HashSet<string> expected = new HashSet<string>( StringComparer.OrdinalIgnoreCase );
        for ( int i = 0; i < SpriteAtlases.Length; i++ )
        {
            expected.Add( SpriteAtlases[ i ].asset.stagingPath );
        }
        for ( int i = 0; i < SingleAssets.Length; i++ )
        {
            expected.Add( SingleAssets[ i ].stagingPath );
        }
        string[] actual = bundle.GetAllAssetNames();
        if ( actual.Length != expected.Count || expected.Count != 464 + ApprovedOmissionCount )
        {
            throw new InvalidOperationException( "Static preview bundle approved asset count mismatch." );
        }
        for ( int i = 0; i < actual.Length; i++ )
        {
            if ( !expected.Contains( actual[ i ] ) )
            {
                throw new InvalidOperationException( "Unexpected asset in static preview bundle: " + actual[ i ] );
            }
        }
        Debug.Log( "SWORDSMAN_OMISSIONS_BUNDLE omissions=1355 assets=1819 portraitSprites=165 uiSprites=431 shopBackdrops=12 campBackdrops=33 propSprites=9 singles=324 fixedTerrainSprites=216 characterDynamicAssets=0 environmentAnimationSlices=12" );
    }

    static void ValidateBuiltBundle( string bundlePath )
    {
        if ( !File.Exists( bundlePath ) )
        {
            throw new FileNotFoundException( "Built HD AssetBundle is missing.", bundlePath );
        }

        AssetBundle bundle = AssetBundle.LoadFromFile( bundlePath );
        if ( bundle == null )
        {
            throw new InvalidOperationException( "Cannot load the built HD AssetBundle." );
        }

        try
        {
            ValidateStaticBundleAssets( bundle );
            for ( int i = 0; i < SpriteAtlases.Length; i++ )
            {
                ValidateAtlasInBundle( bundle, SpriteAtlases[ i ] );
            }
            for ( int i = 0; i < SingleAssets.Length; i++ )
            {
                ValidateSingleInBundle( bundle, SingleAssets[ i ] );
            }
        }
        finally
        {
            bundle.Unload( true );
        }
    }

    static void ValidateSingleInBundle( AssetBundle bundle, ApprovedAsset asset )
    {
        Sprite[] sprites = bundle.LoadAssetWithSubAssets<Sprite>(
            asset.stagingPath.ToLowerInvariant() );
        if ( sprites == null || sprites.Length != 1 )
        {
            throw new InvalidOperationException(
                "Built HD AssetBundle must contain one Sprite for " + asset.label );
        }

        Sprite hdSprite = sprites[ 0 ];
        SourceSprite legacySprite = GetSourceSpriteGeometry( asset.sourceAssetPath );
        if ( legacySprite == null ||
            !Mathf.Approximately( hdSprite.pixelsPerUnit, legacySprite.pixelsPerUnit * SingleScale ) ||
            Mathf.Abs( hdSprite.rect.width - legacySprite.rect.width * SingleScale ) > 0.001f ||
            Mathf.Abs( hdSprite.rect.height - legacySprite.rect.height * SingleScale ) > 0.001f )
        {
            throw new InvalidOperationException(
                "Built HD Sprite scale or PPU mismatch: " + asset.label );
        }

        ValidatePivot( hdSprite, asset.label );
        ValidateWorldGeometry( legacySprite, hdSprite, asset.label );
    }

    static void ValidateAtlasInBundle( AssetBundle bundle, AtlasSpec spec )
    {
        Sprite[] loaded = bundle.LoadAssetWithSubAssets<Sprite>(
            spec.asset.stagingPath.ToLowerInvariant() );
        Dictionary<string, Sprite> byName = new Dictionary<string, Sprite>( StringComparer.Ordinal );
        for ( int i = 0; i < loaded.Length; i++ )
        {
            byName[ loaded[ i ].name ] = loaded[ i ];
        }

        List<SourceSprite> legacySprites = FindLegacySpritesForTexture( spec.asset.sourceAssetPath, spec.allowedSpriteName );
        if ( byName.Count != spec.expectedSpriteCount ||
            legacySprites.Count != spec.expectedSpriteCount )
        {
            throw new InvalidOperationException(
                spec.asset.label + " Sprite count mismatch in built bundle." );
        }

        for ( int i = 0; i < legacySprites.Count; i++ )
        {
            SourceSprite legacySprite = legacySprites[ i ];
            Sprite hdSprite;
            if ( !byName.TryGetValue( legacySprite.name, out hdSprite ) ||
                !RectApproximatelyEqual(
                    hdSprite.rect, GetAtlasRect( legacySprite, spec ) ) ||
                !Mathf.Approximately(
                    hdSprite.pixelsPerUnit,
                    legacySprite.pixelsPerUnit * spec.linearScale ) )
            {
                throw new InvalidOperationException(
                    spec.asset.label + " geometry mismatch: " + legacySprite.name );
            }
            if ( Vector4.Distance( hdSprite.border, legacySprite.border * spec.linearScale ) > 0.001f )
            {
                throw new InvalidOperationException( "Built HD Sprite border mismatch: " + legacySprite.name );
            }
            ValidatePivotMatches( legacySprite, hdSprite, legacySprite.name );
            ValidateWorldGeometry( legacySprite, hdSprite, legacySprite.name );
        }
    }

    static void ValidatePivotMatches( SourceSprite legacySprite, Sprite hdSprite, string label )
    {
        Vector2 legacyPivot = new Vector2(
            legacySprite.pivot.x / legacySprite.rect.width,
            legacySprite.pivot.y / legacySprite.rect.height );
        Vector2 hdPivot = new Vector2(
            hdSprite.pivot.x / hdSprite.rect.width,
            hdSprite.pivot.y / hdSprite.rect.height );
        if ( Vector2.Distance( legacyPivot, hdPivot ) > 0.0001f )
        {
            throw new InvalidOperationException( "Built HD Sprite pivot mismatch: " + label );
        }
    }

    static void ValidatePivot( Sprite sprite, string label )
    {
        Vector2 normalizedPivot = new Vector2(
            sprite.pivot.x / sprite.rect.width,
            sprite.pivot.y / sprite.rect.height );
        if ( Vector2.Distance( normalizedPivot, new Vector2( 0.0f, 1.0f ) ) > 0.0001f )
        {
            throw new InvalidOperationException( "Built HD Sprite pivot mismatch: " + label );
        }
    }

    static void ValidateWorldGeometry( SourceSprite legacySprite, Sprite hdSprite, string label )
    {
        if ( legacySprite == null ||
            Mathf.Abs(
                legacySprite.rect.width / legacySprite.pixelsPerUnit -
                hdSprite.rect.width / hdSprite.pixelsPerUnit ) > 0.0001f ||
            Mathf.Abs(
                legacySprite.rect.height / legacySprite.pixelsPerUnit -
                hdSprite.rect.height / hdSprite.pixelsPerUnit ) > 0.0001f )
        {
            throw new InvalidOperationException( "Built HD Sprite world size mismatch: " + label );
        }
    }

    static bool RectApproximatelyEqual( Rect first, Rect second )
    {
        const float epsilon = 0.0001f;
        return Mathf.Abs( first.x - second.x ) <= epsilon &&
            Mathf.Abs( first.y - second.y ) <= epsilon &&
            Mathf.Abs( first.width - second.width ) <= epsilon &&
            Mathf.Abs( first.height - second.height ) <= epsilon;
    }

    static void EnsureReservedFolderCanBeReplaced( string folder )
    {
        string absoluteFolder = GetAbsoluteProjectPath( folder );
        if ( !Directory.Exists( absoluteFolder ) )
        {
            return;
        }

        string[] files = Directory.GetFiles( absoluteFolder, "*", SearchOption.AllDirectories );
        for ( int i = 0; i < files.Length; i++ )
        {
            string fileName = Path.GetFileName( files[ i ] );
            bool knownStagingFile = folder == StagingFolder &&
                ( fileName.EndsWith( ".png", StringComparison.OrdinalIgnoreCase ) ||
                fileName.EndsWith( ".meta", StringComparison.OrdinalIgnoreCase ) );
            bool knownBundleFile = folder == StreamingFolder &&
                ( fileName == BundleName || fileName == BundleName + ".meta" );

            if ( !knownStagingFile && !knownBundleFile )
            {
                throw new InvalidOperationException(
                    "Reserved HD folder contains an unexpected file: " + files[ i ] );
            }
        }

        AssetDatabase.DeleteAsset( folder );
        AssetDatabase.Refresh();
    }

    static string GetAbsoluteProjectPath( string projectRelativePath )
    {
        return Path.GetFullPath( Path.Combine(
            Application.dataPath, "..", projectRelativePath ) );
    }

    static string GetSha256( string path )
    {
        using ( SHA256 hash = SHA256.Create() )
        using ( FileStream stream = File.OpenRead( path ) )
        {
            byte[] bytes = hash.ComputeHash( stream );
            return BitConverter.ToString( bytes ).Replace( "-", string.Empty ).ToLowerInvariant();
        }
    }
}
